#include <bits/stdc++.h>
using namespace std;
#define int long long
const int MOD1=998244353;
const int MOD2=1000000007;
int totalAnswer;
int totalN;
int count1Var;
vector<int> valArr[7];
int sumArr[7];
void generate(int level,int prefixSum){
	if(level==7) return;
	valArr[level].push_back((count1Var - prefixSum + MOD1) % MOD1);
	sumArr[level] += (count1Var - prefixSum + MOD1) % MOD1;
	count1Var++;
	for(int digit=0; digit<=9; ++digit){
		generate(level+1, prefixSum*10+digit);
	}
}
bool inInterval(int x){
	const int half=1000000;
	return x*half+999999 <= totalN && x*half*10 > totalN;
}
int count2Var;
int powTenArr[7]={1,10,100,1000,10000,100000,1000000};
void explore(int level,int number){
	if(number > totalN) return;
	if(inInterval(number)){
		for(int i=0; i<=6; ++i){
			int offset = ((count2Var+1 - (number*powTenArr[i])) % MOD1 + MOD1) % MOD1;
			int pos = lower_bound(valArr[i].begin(), valArr[i].end(), MOD1 - offset) - valArr[i].begin();
			totalAnswer += (sumArr[i] + offset * (int)valArr[i].size() - MOD1 * ((int)valArr[i].size() - pos)) % MOD2;
			totalAnswer %= MOD2;
		}
		count2Var += count1Var;
	}
	else{
		count2Var++;
		totalAnswer += ((count2Var - number) % MOD1 + MOD1) % MOD1;
		totalAnswer %= MOD2;
		for(int digit=0; digit<=9; ++digit){
			if(level==0 && digit==0) continue;
			explore(level+1, number*10+digit);
		}
	}
}
int main(){
	cin >> totalN;
	generate(0,0);
	for(int i=0; i<=6; ++i) sort(valArr[i].begin(), valArr[i].end());
	count2Var = -1;
	explore(0,0);
	cout << totalAnswer << "\n";
}
